draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // draw dog
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2, H/2 + 100);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 75);
  ctx.lineTo(W/2 - 25 + 20 * Math.sin(t), H/2 + 125);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 75);
  ctx.lineTo(W/2 + 25 - 20 * Math.sin(t), H/2 + 125);
  ctx.stroke();

  // draw owner
  ctx.beginPath();
  ctx.arc(W/2 - 150, H/2, 30, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 150, H/2 + 30);
  ctx.lineTo(W/2 - 150, H/2 + 80);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 150, H/2 + 55);
  ctx.lineTo(W/2 - 175, H/2 + 90);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 150, H/2 + 55);
  ctx.lineTo(W/2 - 125, H/2 + 90);
  ctx.stroke();

  // draw speech bubble
  ctx.beginPath();
  ctx.arc(W/2 - 170, H/2 - 50, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.font = '20px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = 'black';
  ctx.fillText('Sit!', W/2 - 170, H/2 - 50);

  // draw dog's ignoring expression
  ctx.beginPath();
  ctx.arc(W/2 + 10 * Math.sin(t), H/2 - 40, 10, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W/2 + 10 * Math.cos(t), H/2 - 60, 10, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 - 20);
  ctx.lineTo(W/2 + 20 * Math.sin(t), H/2 - 40);
  ctx.stroke();

  ctx.restore();
}
